// HasGenerationJob applies the HasEdge predicate on the "generation_job" edge.
func HasGenerationJob() predicate.AIAsset {
	return predicate.AIAsset(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, GenerationJobTable, GenerationJobColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasGenerationJobWith applies the HasEdge predicate on the "generation_job" edge with a given conditions (other predicates).
func HasGenerationJobWith(preds ...predicate.AIGenerationJob) predicate.AIAsset {
	return predicate.AIAsset(func(s *sql.Selector) {
		step := newGenerationJobStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

