// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AIAsset) predicate.AIAsset {
	return predicate.AIAsset(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AIAsset) predicate.AIAsset {
	return predicate.AIAsset(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AIAsset) predicate.AIAsset {
	return predicate.AIAsset(sql.NotPredicates(p))
}
